catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || !newValue) return;

    var ga = new GlideAjax('VenueUtils');
    ga.addParam('sysparm_name', 'getVenueDetails');
    ga.addParam('sysparm_venue_name', newValue);

    ga.getXMLAnswer(function(response) {
        var data = JSON.parse(response);

        if (data.error) {
            g_form.showFieldMsg('venue_name', data.error, 'error');
            return;
        }

        if (!data.available) {
            g_form.showFieldMsg('u_venue_name', 'This venue is not available.', 'error');
        }

        g_form.setValue('location', data.location);
        g_form.setValue('capacity', data.capacity);
        g_form.setValue('contact_person', data.contact_person);
        g_form.setValue('contact_number', data.contact_number);
    });
}
